 private void buildHome(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(12));root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff070b18,0xff101b32,0xff080c18}));
 TextView title=label("S U M A X",26,accent());heading=title;title.setTypeface(null,1);root.addView(title);root.addView(label("N E U R A L   I N T E R F A C E",10,0xff91a4bf));
 FrameLayout stage=new FrameLayout(this);root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));View reactor=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()*.76f,r=Math.min(getWidth()*.30f,getHeight()*.18f),a=SystemClock.uptimeMillis()%8000/8000f*360;int color=accent();p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(x,y,r*1.3f,new int[]{color,0x223b80ff,0},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,r*1.3f,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);for(int k=0;k<4;k++){float z=r*(.45f+k*.18f);p.setColor(color);p.setAlpha(90+k*35);p.setStrokeWidth(dp(k==3?2:1));c.drawArc(x-z,y-z,x+z,y+z,a*(k%2==0?1:-1)+k*45,240,false,p);}p.setAlpha(255);for(int k=0;k<48;k++){double t=k*Math.PI/24;float z=r*1.1f;c.drawLine(x+(float)Math.cos(t)*z,y+(float)Math.sin(t)*z,x+(float)Math.cos(t)*(z+dp(k%4==0?8:3)),y+(float)Math.sin(t)*(z+dp(k%4==0?8:3)),p);}p.setStyle(Paint.Style.FILL);for(int k=0;k<18;k++){double angle=k*Math.PI/9+a*Math.PI/180;float orbit=r*(1.18f+.12f*(float)Math.sin(angle*3));p.setColor(color);p.setAlpha(90+(k%3)*45);c.drawCircle(x+(float)Math.cos(angle)*orbit,y+(float)Math.sin(angle)*orbit,dp(k%3==0?2:1),p);}p.setAlpha(255);if(isShown()&&hasWindowFocus())postInvalidateDelayed(33);}public void onWindowFocusChanged(boolean f){super.onWindowFocusChanged(f);if(f)invalidate();}};reactorView=reactor;stage.addView(reactor,new FrameLayout.LayoutParams(-1,-1));avatar=new AssistantView(this);avatar.setMode(mode);stage.addView(avatar,new FrameLayout.LayoutParams(-1,0,Gravity.TOP));stage.addOnLayoutChangeListener((v,l,t,rr,b,ol,ot,orr,ob)->{int h=Math.max(0,Math.round((b-t)*.53f));android.view.ViewGroup.LayoutParams ap=avatar.getLayoutParams();if(ap.height!=h){ap.height=h;avatar.setLayoutParams(ap);}});state=label(modes[mode]+" • Ready",15,0xffe6f2ff);state.setMaxLines(3);state.setEllipsize(android.text.TextUtils.TruncateAt.END);state.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);state.setPadding(dp(8),dp(8),dp(8),dp(8));root.addView(state);
 LinearLayout modesRow=new LinearLayout(this);for(int i=0;i<3;i++){final int n=i;TextView t=action(modes[i],()->{requestGeneration++;mode=n;getPreferences(0).edit().putInt("mode",n).apply();avatar.setMode(n);state.setText(modes[n]+" • Ready");refreshModeUi();});modeTiles[i]=t;tile(modesRow,t);}root.addView(modesRow);refreshModeUi();
 LinearLayout dock=new LinearLayout(this);tile(dock,action("Apps",()->showApps()));tile(dock,action("Voice",()->{Intent i=new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);try{avatar.setEmotion(3);state.setText("Listening…");startActivityForResult(i,42);}catch(ActivityNotFoundException e){avatar.setEmotion(4);state.setText("Speech recognition unavailable");}}));tile(dock,action("Settings",()->configureOnline()));root.addView(dock);
 LinearLayout composer=new LinearLayout(this);EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(-1);input.setHintTextColor(0xff91a4bf);input.setHint("Talk to SUMAX");input.setPadding(dp(14),dp(8),dp(14),dp(8));input.setMinHeight(dp(48));input.setBackground(panel(0xff101b32,0xff344763));input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEND);input.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_SEND){String msg=input.getText().toString();input.setText("");respond(msg);return true;}return false;});composer.addView(input,new LinearLayout.LayoutParams(0,-2,1));composer.addView(action("Send",()->{String s=input.getText().toString();input.setText("");respond(s);}),new LinearLayout.LayoutParams(-2,-2));root.addView(composer);setContentView(root);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void refreshModeUi(){if(heading!=null)heading.setTextColor(accent());for(int i=0;i<modeTiles.length;i++){TextView t=modeTiles[i];if(t!=null){t.setSelected(i==mode);t.setTextColor(i==mode?accent():0xffedf4ff);t.setBackground(panel(i==mode?0xff23324a:0xff142037,i==mode?accent():0xff344763));t.setContentDescription(modes[i]+(i==mode?", selected":""));}}if(reactorView!=null)reactorView.invalidate();}
 private void showApps(){Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);list.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(12),dp(12),dp(12));body.setBackgroundColor(0xff101b32);EditText search=new EditText(this);search.setHint("Search apps");search.setTextColor(-1);search.setHintTextColor(0xff91a4bf);body.addView(search);GridView grid=new GridView(this);grid.setNumColumns(3);grid.setVerticalSpacing(dp(12));body.addView(grid,new LinearLayout.LayoutParams(-1,Math.min(dp(440),getResources().getDisplayMetrics().heightPixels/2)));java.util.ArrayList<ResolveInfo> filtered=new java.util.ArrayList<>(list);BaseAdapter adapter=new BaseAdapter(){public int getCount(){return filtered.size();}public Object getItem(int p){return filtered.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){ResolveInfo a=filtered.get(p);LinearLayout cell=new LinearLayout(MainActivity.this);cell.setOrientation(1);cell.setGravity(Gravity.CENTER);ImageView icon=new ImageView(MainActivity.this);icon.setImageDrawable(a.loadIcon(getPackageManager()));cell.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView name=label(a.loadLabel(getPackageManager()).toString(),11,0xffedf4ff);name.setMaxLines(2);cell.addView(name);return cell;}};grid.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("App library").setView(body).setNegativeButton("Close",null).create();grid.setOnItemClickListener((p,v,pos,id)->{ResolveInfo a=filtered.get(pos);Intent launch=new Intent(Intent.ACTION_MAIN);launch.addCategory(Intent.CATEGORY_LAUNCHER);launch.setClassName(a.activityInfo.packageName,a.activityInfo.name);try{startActivity(launch);dialog.dismiss();}catch(Exception e){state.setText("Unable to open app");}});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){filtered.clear();for(ResolveInfo a:list)if(a.loadLabel(getPackageManager()).toString().toLowerCase(java.util.Locale.ROOT).contains(s.toString().toLowerCase(java.util.Locale.ROOT)))filtered.add(a);adapter.notifyDataSetChanged();}public void afterTextChanged(android.text.Editable e){}});dialog.show();}

 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42){avatar.setEmotion(0);state.setText(modes[mode]+" • Ready");}if(request==42&&result==RESULT_OK&&data!=null){java.util.ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty())respond(words.get(0));}}
 private void respond(String input){requestGeneration++;String q=input.trim().toLowerCase(java.util.Locale.ROOT);if(q.isEmpty()){state.setText("Enter a command or question.");return;}String answer;int emotion=1;if(q.equals("time")||q.equals("what time is it"))answer=java.text.DateFormat.getTimeInstance().format(new java.util.Date());else if(q.equals("date")||q.equals("what is the date"))answer=java.text.DateFormat.getDateInstance().format(new java.util.Date());else if(q.equals("hello")||q.equals("hi"))answer="Hello. "+modes[mode]+" is ready.";else if(q.equals("battery")){android.os.BatteryManager bm=(android.os.BatteryManager)getSystemService(BATTERY_SERVICE);int level=bm.getIntProperty(android.os.BatteryManager.BATTERY_PROPERTY_CAPACITY);answer=level>=0&&level<=100?"Battery: "+level+"%":"Battery level unavailable.";}else if(q.startsWith("open ")){answer=openNamedApp(q.substring(5).trim());}else if(q.equals("help"))answer="Try hello, time, date, battery, open an app by name, or switch to Hunter, Shadow or Guardian.";else if(q.startsWith("switch to ")){int found=-1;for(int j=0;j<modes.length;j++)if(q.equals("switch to "+modes[j].toLowerCase(java.util.Locale.ROOT)))found=j;if(found>=0){mode=found;getPreferences(0).edit().putInt("mode",mode).apply();avatar.setMode(mode);refreshModeUi();answer=modes[mode]+" activated.";}else answer="Unknown mode.";}else{askOnline(input);return;}avatar.setEmotion(emotion);state.setText(modes[mode]+" • "+answer);if(speechReady)speech.speak(answer,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"sumax-response");}
 private String openNamedApp(String name){if(name.isEmpty())return "Please specify an app name.";Intent query=new Intent(Intent.ACTION_MAIN);query.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> matches=new java.util.ArrayList<>();for(ResolveInfo info:getPackageManager().queryIntentActivities(query,0)){if(info.loadLabel(getPackageManager()).toString().equalsIgnoreCase(name)&&!info.activityInfo.packageName.equals(getPackageName()))matches.add(info);}if(matches.size()!=1)return matches.isEmpty()?"App not found. Try its exact name.":"Multiple apps match. Use All apps.";ResolveInfo info=matches.get(0);Intent launch=new Intent(Intent.ACTION_MAIN);launch.addCategory(Intent.CATEGORY_LAUNCHER);launch.setClassName(info.activityInfo.packageName,info.activityInfo.name);try{startActivity(launch);return "Opening "+info.loadLabel(getPackageManager());}catch(Exception e){return "Unable to open app.";}}
 private int requestGeneration;
 private void configureOnline(){EditText endpoint=new EditText(this);endpoint.setSingleLine(true);endpoint.setHint("https://your-server/chat");endpoint.setText(getPreferences(0).getString("endpoint",""));EditText token=new EditText(this);token.setHint("Gateway access token");token.setInputType(129);token.setText(getPreferences(0).getString("gateway_token",""));LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);fields.addView(endpoint);fields.addView(token);new AlertDialog.Builder(this).setTitle("Trusted HTTPS AI gateway").setMessage("Use your own trusted server. Unknown offline commands will be sent to this server. No API key is stored in the app.").setView(fields).setPositiveButton("Save",(d,w)->{String value=endpoint.getText().toString().trim();try{java.net.URI uri=new java.net.URI(value);if(!value.isEmpty()&&(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null))throw new Exception();getPreferences(0).edit().putString("endpoint",value).putString("gateway_token",token.getText().toString().trim()).apply();}catch(Exception e){Toast.makeText(this,"Enter a valid HTTPS address",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();}
 private void askOnline(String input){String endpoint=getPreferences(0).getString("endpoint","");if(endpoint.isEmpty()){state.setText("Online AI is not configured. Offline commands remain available.");avatar.setEmotion(0);return;}final int generation=++requestGeneration;final String selected=modes[mode];avatar.setEmotion(2);state.setText("Thinking…");new Thread(()->{String answer;boolean success=false;javax.net.ssl.HttpsURLConnection connection=null;try{connection=(javax.net.ssl.HttpsURLConnection)new java.net.URL(endpoint).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(20000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");String token=getPreferences(0).getString("gateway_token","");if(!token.isEmpty())connection.setRequestProperty("Authorization","Bearer "+token);org.json.JSONObject body=new org.json.JSONObject();body.put("message",input);body.put("mode",selected);try(java.io.OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}if(connection.getResponseCode()!=200)throw new java.io.IOException();try(java.io.InputStream in=connection.getInputStream();java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream()){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1){if(buffer.size()+n>65536)throw new java.io.IOException();buffer.write(bytes,0,n);}answer=new org.json.JSONObject(buffer.toString("UTF-8")).getString("reply");success=true;}}catch(Exception e){answer="Online AI unavailable. Try help for offline commands.";}finally{if(connection!=null)connection.disconnect();}final String reply=answer;final boolean ok=success;runOnUiThread(()->{if(isFinishing()||isDestroyed()||generation!=requestGeneration)return;avatar.setEmotion(ok?1:4);state.setText(reply);if(speechReady)speech.speak(reply,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"sumax-online");});}).start();}
